{ "appendquerystring": false, "associatecurrentportaluser": false, "attachfile": false, "attachfileallowmultiple": true, "attachfilelabel": "[{"LCID":1025,"Value":""},{"LCID":1033,"Value":"Include evidence of expenses"}]", "attachfilemaxsize": 500, "attachfilerequired": false, "attachfilerequirederrormessage": "[{"LCID":1025,"Value":""},{"LCID":1033,"Value":"Please attach evidence"}]", "attachfilerestrictaccept": false, "attachfilesaveoption": 756150000, "attachfilestoragelocation": 756150000, "autogeneratesteps": false, "captcharequired": false, "entityname": "new_timesheetcost", "entitypermissionsenabled": true, "entitysourcetype": 0, "forceallfieldsrequired": false, "formname": "Portal", "geolocation_displaymap": false, "geolocation_enabled": false, "geolocation_maptype": 756150000, "hideformonsuccess": false, "mode": 100000000, "onsuccess": 756150001, "populatereferenceentitylookupfield": false, "portaluserlookupattributeisactivityparty": false, "recommendedfieldsrequired": true, "recordsourceallowcreateonnull": false, "redirecturlappendentityidquerystring": true, "redirecturlquerystringname": "expenseid", "redirectwebpage": "322e9f40-d034-6bea-2d63-a21d3a482ac6", "referenceentityshowreadonlyform": false, "referencequerystringisprimarykey": true, "registerstartupscript": "$(document).ready(function(){
 var expenseFee=0,expenseTotal=0;
 const expenseFeePercent = parseFloat(window.parent.parentExpenseFeePercent) || 0;

 $('#new_expensecostscurrency').on('input',calculateExpenseTotal);
 $('#new_percentofbill').closest('tr').hide();
 $('#new_expensebilltotal').closest('tr').hide();
 $('#new_expensepaytotal').closest('tr').hide();

 function calculateExpenseTotal(){
 let expenseCost = $('#new_expensecostscurrency').val();
 let expense = parseFloat(expenseCost) || 0;
 
 expenseFee = expense * (expenseFeePercent/100);
 expenseTotal = expense + expenseFee;
 
 $('#new_percentofbill').val(Number(expenseFee.toFixed(2)));
 $('#new_expensebilltotal').val(Number(expenseTotal.toFixed(2)));
 $('#new_expensepaytotal').val(Number(expense.toFixed(2)));
 }
});", "renderwebresourcesinline": false, "setentityreference": false, "showcaptchaforauthenticatedusers": false, "showownerfields": false, "showunsupportedfields": false, "tabname": "insertdetailedexpense", "tooltipenabled": true, "validationsummarylinksenabled": true }
